begin;
create extension if not exists pgtap with schema extensions;
select plan(22);

select has_table('public', 'shop_feature_locks', 'per-route lock status table exists');
select has_table('public', 'shop_feature_lock_secrets', 'per-route bcrypt hashes are stored separately');
select has_table('public', 'shop_feature_lock_attempts', 'server-side per-route attempt limits are stored');
select has_table('public', 'shop_feature_lock_peppers', 'private per-shop HMAC key material exists to enforce PIN uniqueness');
select ok((select relrowsecurity from pg_class where oid='public.shop_feature_locks'::regclass), 'feature lock status has RLS enabled');
select ok((select relforcerowsecurity from pg_class where oid='public.shop_feature_locks'::regclass), 'feature lock status forces RLS');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.shop_feature_lock_secrets'::regclass), 'PIN hash table forces RLS');
select ok(has_table_privilege('authenticated','public.shop_feature_locks','SELECT'), 'authenticated staff can read safe lock status');
select ok(not has_table_privilege('authenticated','public.shop_feature_locks','INSERT') and not has_table_privilege('authenticated','public.shop_feature_locks','UPDATE') and not has_table_privilege('authenticated','public.shop_feature_locks','DELETE'), 'clients cannot write or delete lock status directly');
select ok(not has_table_privilege('authenticated','public.shop_feature_lock_secrets','SELECT') and not has_table_privilege('authenticated','public.shop_feature_lock_secrets','INSERT') and not has_table_privilege('authenticated','public.shop_feature_lock_secrets','UPDATE'), 'authenticated clients cannot read or write PIN hashes directly');
select ok(not has_table_privilege('authenticated','public.shop_feature_lock_peppers','SELECT') and not has_table_privilege('authenticated','public.shop_feature_lock_peppers','INSERT'), 'authenticated clients cannot read or write HMAC key material');
select ok(not exists (select 1 from information_schema.columns where table_schema='public' and table_name='shop_feature_locks' and column_name ilike '%hash%'), 'realtime-readable status contains no PIN hash');
select ok(not exists (select 1 from information_schema.columns where table_schema='public' and table_name='shop_feature_locks' and column_name in ('pin_scope','shared_pin_configured')), 'shared PIN scope is removed');
select ok(exists (select 1 from pg_policies where schemaname='public' and tablename='shop_feature_locks' and policyname='shop_feature_locks_member_read' and cmd='SELECT' and qual ilike '%has_shop_role%'), 'lock status reads are restricted to active shop members');
select ok(to_regprocedure('public.set_shop_feature_lock_pin(uuid,text,text)') is not null, 'manager can set one route PIN');
select ok(to_regprocedure('public.set_shop_feature_lock(uuid,text,boolean)') is not null, 'manager can toggle one route lock');
select ok(to_regprocedure('public.set_shop_feature_lock(uuid,text,boolean,text)') is null, 'scope-based toggle RPC is removed');
select ok(to_regprocedure('public.set_all_shop_feature_locks(uuid,boolean)') is not null, 'manager bulk lock RPC exists');
select ok(to_regprocedure('public.verify_shop_feature_lock_pin(uuid,text,text)') is not null, 'server-side per-route PIN verification RPC exists');
select ok(has_function_privilege('authenticated','public.set_shop_feature_lock_pin(uuid,text,text)','EXECUTE') and not has_function_privilege('anon','public.set_shop_feature_lock_pin(uuid,text,text)','EXECUTE'), 'PIN update is authenticated-only');
select ok(pg_get_functiondef('public.set_shop_feature_lock_pin(uuid,text,text)'::regprocedure) ilike '%has_shop_role%' and pg_get_functiondef('public.set_shop_feature_lock_pin(uuid,text,text)'::regprocedure) ilike '%manager%' and pg_get_functiondef('public.set_shop_feature_lock_pin(uuid,text,text)'::regprocedure) ilike '%FEATURE_LOCK_PIN_MUST_BE_UNIQUE%', 'PIN setter is manager-only and refuses reuse across routes');
select ok(pg_get_functiondef('public.verify_shop_feature_lock_pin(uuid,text,text)'::regprocedure) ilike '%feature_key = p_feature_key%' and pg_get_functiondef('public.verify_shop_feature_lock_pin(uuid,text,text)'::regprocedure) ilike '%crypt%' and pg_get_functiondef('public.verify_shop_feature_lock_pin(uuid,text,text)'::regprocedure) ilike '%blocked_until%' and pg_get_functiondef('public.verify_shop_feature_lock_pin(uuid,text,text)'::regprocedure) ilike '%pg_advisory_xact_lock%', 'verification uses this route key only, bcrypt comparison, and rate limiting');
select * from finish();
rollback;
